package main

import (
	"crypto/sha256"
	"fmt"
)

func hashPassword(password string) string {
	hash := sha256.Sum256([]byte(password))
	return fmt.Sprintf("%x", hash)
}

func main() {
	password := "jdpassword"
	hashedPassword := hashPassword(password)
	fmt.Println("Hashed Password:", hashedPassword)
}
